import json

# Read zip_code.json
with open('json/zip_code.json', 'r') as f:
    zip_data = json.load(f)

# Get all Illinois zip codes
illinois_zips = set()
for record in zip_data['records']:
    if record.get('state') == 'Illinois':
        zip_code = record.get('zip_code')
        if isinstance(zip_code, int):
            illinois_zips.add(str(zip_code))
        else:
            illinois_zips.add(zip_code)

print(f"Found {len(illinois_zips)} Illinois zip codes")
print(f"Sample Illinois zips: {list(illinois_zips)[:10]}")

# Read member.csv
import csv
members_from_il = []
with open('csv/member.csv', 'r') as f:
    reader = csv.DictReader(f)
    for row in reader:
        member_zip = row.get('zip', '')
        if member_zip and member_zip in illinois_zips:
            members_from_il.append({
                'first_name': row['first_name'],
                'last_name': row['last_name']
            })

print(f"Found {len(members_from_il)} members from Illinois")
for m in members_from_il:
    print(f"{m['first_name']} {m['last_name']}")

